const tk = (s) => (s.match(/@@[LC]\d+@@/g) || []).sort();
const out = src.map((o) => {
  const { prefix, tail } = splitLine(o.masked);
  const ru = M[o.line];
  const tr = ru !== undefined ? prefix + ru : prefix + tail;
  const a = tk(o.masked), b = tk(tr);
  if (a.length !== b.length || a.some((v, i) => v !== b[i])) {
    console.error("FALLBACK line", o.line);
    return { line: o.line, translated: o.masked };
  }
  return { line: o.line, translated: tr };
});

writeFileSync(outPath, JSON.stringify(out, null, 2) + "\n");
console.log("batch_01 written:", out.length, "entries; translated:", Object.keys(M).length);